 const exportColumns={'图纸评审':[['评审编号',x=>x.code],['图号',x=>drawingMap[x.drawing_id]?.code||''],['图纸名称',x=>drawingMap[x.drawing_id]?.name||x.name||''],['版本',x=>versionMap[x.version_id]?.version||''],['专业',x=>disciplineText[x.discipline]||x.discipline||''],['状态',x=>statusText[x.status]||x.status||''],['问题数',x=>Number(x.issue_count||0)],['发起人',x=>x.created_by_name||''],['截止日期',x=>x.due_on||'']],'图纸发布':[['图号',x=>drawingMap[x.drawing_id]?.code||''],['图纸名称',x=>drawingMap[x.drawing_id]?.name||''],['本次发布版本',x=>versionMap[x.version_id]?.version||''],['发布前版本',x=>{const d=drawingMap[x.drawing_id],v=versionMap[x.version_id];return x.status==='released'&&d?.current_version===v?.version?(versions.filter(y=>y.drawing_id===x.drawing_id&&y.status==='superseded').sort((a,b)=>String(b.released_at||b.id).localeCompare(String(a.released_at||a.id)))[0]?.version||''):(d?.current_version||'')}],['版本链路',x=>{const d=drawingMap[x.drawing_id],v=versionMap[x.version_id],before=x.status==='released'&&d?.current_version===v?.version?(versions.filter(y=>y.drawing_id===x.drawing_id&&y.status==='superseded').sort((a,b)=>String(b.released_at||b.id).localeCompare(String(a.released_at||a.id)))[0]?.version||''):(d?.current_version||'');return before+' → '+(v?.version||'')}],['审核状态',x=>x.status==='pending'?'待审批':x.status==='approved'||x.status==='released'?'审批通过':x.status==='rejected'?'已退回':'—'],['发布状态',x=>x.status==='draft'?'待发布':x.status==='released'?'已发布':x.status==='cancelled'?'已取消':statusText[x.status]||x.status||''],['是否重大变更',x=>x.major_change?'是':'否'],['审核通过时间',x=>fmt(x.approved_at)],['建议生效日期',x=>x.suggested_effective_on||''],['影响对象数',x=>links.filter(link=>link.drawing_id===x.drawing_id&&['active','needs_review'].includes(link.status)).length]],'图纸变更':[['变更单号',x=>x.code],['图号',x=>drawingMap[x.drawing_id]?.code||''],['图纸名称',x=>drawingMap[x.drawing_id]?.name||''],['原版本',x=>versionMap[x.source_version_id]?.version||''],['新版本',x=>versionMap[x.target_version_id]?.version||''],['变更类型',x=>changeText[x.change_type]||x.change_type||''],['变更等级',x=>x.change_level==='major'?'重大变更':'一般变更'],['状态',x=>statusText[x.status]||x.status||''],['申请时间',x=>fmt(x.submitted_at||x.created_at)]],'发放记录':[['发放单号',x=>x.code],['图号',x=>drawingMap[x.drawing_id]?.code||''],['图纸名称',x=>drawingMap[x.drawing_id]?.name||''],['发放版本',x=>versionMap[x.version_id]?.version||''],['接收对象',x=>x.recipient_name||''],['接收类型',x=>recipientText[x.recipient_type]||x.recipient_type||''],['发放方式',x=>methodText[x.method]||x.method||''],['发放状态',x=>statusText[x.status]||x.status||''],['确认状态',x=>x.confirmation_status==='confirmed'?'全部已确认':x.confirmation_status==='partial'?'部分已确认':'待确认'],['回执状态',x=>x.receipt_status==='received'?'已回执':x.receipt_status==='pending'?'待回执':'无需回执'],['发放时间',x=>fmt(x.sent_at||x.created_at)]],'客户图纸':[['客户图号',x=>x.code],['图纸名称',x=>x.name],['客户名称',x=>customerMap[x.customer_id]?.name||''],['密级',x=>x.confidentiality==='general'?'一般':x.confidentiality==='confidential'?'机密':'绝密'],['使用范围',x=>x.usage_scope==='project_only'?'仅限本项目':x.usage_scope==='cross_project'?'可跨项目使用':'仅限指定人员'],['版本',x=>x.version],['状态',x=>statusText[x.status]||x.status||''],['接收日期',x=>x.received_on||''],['接收人',x=>x.received_by_name||'']]};
 function exportTab(){const cols=exportColumns[tab]||[['图号',x=>x.code],['图纸名称',x=>x.name],['当前版本',x=>x.current_version],['状态',x=>statusText[x.status]||x.status]];try{const q=String.fromCharCode(34),nl=String.fromCharCode(10),bom=String.fromCharCode(65279),cell=v=>q+String(v==null?'':v).split(q).join(q+q)+q,csv=[cols.map(c=>c[0])].concat(filtered.map(row=>cols.map(c=>c[1](row)))).map(r=>r.map(cell).join(',')).join(nl),blob=new Blob([bom+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(pageTitles[tab]||'图纸')+'-'+new Date().toISOString().slice(0,10)+'.csv';a.click();URL.revokeObjectURL(url);setToast('已导出 '+filtered.length+' 条'+(pageTitles[tab]||'记录'));}catch(e){setToast('导出失败：'+String(e.message||e))}}
